/**
 * Language is a view over the server-backed user preferences; the
 * `useLanguage()` API is unchanged, only the storage moved.
 */
export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { preferences, updatePreferences } = useUserPreferences();

  // Guard against a stored code that no longer has a translation table.
  const language: Language = Object.keys(translations).includes(preferences.language)
    ? (preferences.language as Language)
    : 'en';

  const setLanguage = (newLanguage: Language) => {
    void updatePreferences({ language: newLanguage as any });
  };

  // Translation function
  const t = (key: string): string => {
    return translations[language]?.[key] || key;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = (): LanguageContextType => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};